  "rawSignal": {
    "additionalTimestamp": "2024-04-24T08:34:12.000Z",
    "metadata": { "platform": "ANDROID" },
    "signal": {
      "position": {
        "point": {
          "latE7": 297391234,
          "lngE7": -950125678
        },
